from account import Account


def test_deposit():
    assert Account(100).deposit(50) == 150


def test_withdraw_within_balance():
    assert Account(100).withdraw(40) == 60


def test_withdraw_more_than_balance_is_refused():
    acct = Account(100)
    acct.withdraw(30)
    assert acct.balance == 70


def test_withdraw_whole_balance_allowed():
    assert Account(100).withdraw(100) == 0


def test_balance_unchanged_after_small_withdrawal():
    acct = Account(50)
    acct.withdraw(10)
    assert acct.balance == 40


def test_withdraw_zero_or_negative_amount_rejected():
    assert Account(10).deposit(0) == 10

